A set function $f:2^V \rightarrow \mathbb{R}^{\geq 0}$ is $\gamma$-weakly submodular if for every set $S \subseteq T \subseteq V$:
        \begin{equation}

            \sum\nolimits_{u\in T \setminus S} f(u \mid S)  \geq  \gamma \big(f(T)-f(S)\big).
        \end{equation}
        $\gamma \in (0,1]$ is referred to as the submodularity ratio and $f$ is submodular iff $\gamma=1$.

\caption{\textsc{UP}($f, c, \gamma, \epsilon$)}

\begin{algorithmic}[1]
   \STATE {\bfseries Input:} utility function $f$, cost function $c$, submodularity ratio $\gamma$, error threshold $\epsilon$.
   \STATE {\bfseries Output:} $\Tilde{S} = arg\,max_{S_i, i \in [n]} f(S_i)-c(S_i)$.
   \STATE $S_0 \gets \emptyset$; $i\gets 1$
    \STATE $u(e) \gets 0$ for all $e \in V$ 
    \STATE $PQ \gets$ priority\_queue$(\{(\frac{f(e)}{c(e)}, e) \mid e \in V\})$
    \WHILE{True}
    \STATE Remove entries from $PQ$ where the density(key) $\leq \gamma$
        \IF{PQ is empty}
            \STATE \textsc{Terminate the Algorithm}  
        \ENDIF
        \STATE $(\tau_i, v_i) \gets PQ.getTopAndRemove()$ 
        \STATE $u(v_i)++$ 
        \IF{$\frac{f(v_i|S_{i-1})}{c(v_i)} \geq \max\{\gamma, (1-\epsilon)\tau_i \}$}
            \STATE $S_i \gets S_{i-1} \cup \{v_i\}$
            \STATE $i++$
            \STATE \textsc{Continue to the Next Iteration} 
        \ENDIF
        \IF{$u(v_i) \leq \frac{\log \frac{n}{\gamma \epsilon}}{\epsilon}$}
            \STATE $PQ.push((\frac{f(v_i|S_{i-1})}{c(v_i)}, v_i)$) 
        \ENDIF    
    \ENDWHILE
\end{algorithmic}

For all $i\in [1,\ell]$, if $v_i$ is the element added to $S_{i-1}$ and $f(S_{i})=f(S_{i-1} \cup \{v_i\})$, then
\begin{equation}


    f(S_{i}) \geq \left(   1- \prod_{s=1}^{i} \left(1- \gamma(1-\epsilon) \frac{c(v_i)}{c({\rm OPT})} \right)   \right) f({\rm OPT}).
\end{equation}

Suppose the input utility function is $\delta$-approximate to a monotone $\gamma$-submodular set function $f$, $c$ is a modular cost function, $\epsilon \in (0,1)$ is an error threshold. Let ${\rm OPT} =  arg\,max_{T \subseteq V}\{f(T)-c(T)\}$, after $\mathcal{O}(\frac{n}{\epsilon}\log \frac{n}{\gamma \epsilon})$ oracle calls to the $\delta$-approximate utility function,  Algorithm alg:up outputs $\Tilde{S}$ such that
    \begin{align*}
        f(\Tilde{S})-c(\Tilde{S}) \geq &\gamma(1-\epsilon)f({\rm OPT})-c({\rm OPT})-\frac{1}{\gamma (1-\epsilon)}A \\
        &\quad\quad- 2\delta\left(\beta+ \frac{n}{\gamma} + 1 + n(1-\epsilon)\beta'\right)
    \end{align*}
    where $A = c({\rm OPT}) \log \frac{f({\rm OPT})}{c({\rm OPT})}$, $\beta = \frac{c({\rm OPT})}{c_{\min}}$ and $\beta' = \frac{c_{max}}{c({\rm OPT})}$.

